        claimsCenter.mobileAppBackend -> claimsCenter.notificationService

        claimsCenter.claimsIntakeService -> claimsCenter.triageService "Hands accepted claims"
        claimsCenter.triageService -> claimsCenter.assessmentService "Routes claims"
        claimsCenter.assessmentService -> claimsCenter.payoutService "Requests settlements"

        claimsCenter.fraudScreeningService -> claimsDataBureau "Consults"
        claimsCenter.payoutService -> clearingHouse "Executes settlements through"

        claimsCenter.assignmentService -> claimsCenter.adjusterWorkbench "Routes claims"

        claimsCenter.documentService -> claimsCenter.documentStore "Reads from"
        claimsCenter.batchScheduler -> claimsCenter.claimsDatabase "Reads and writes"
        claimsCenter.batchScheduler -> claimsCenter.policyDatabase "Reads and writes"
