input.code:
const dsl = `workspace "Claims Center" "C4 model of the insurance claims platform" {

    model {
        policyholder = person "Policyholder" {
            description "Reports claims and tracks their progress"
        }
        adjuster = person "Adjuster" {
            description "Staff member who processes assigned claims"
        }

        claimsCenter = softwareSystem "Claims Center" {
            description "The insurance company's claims platform"

            webPortal = container "Web Portal" {
                description "Where policyholders report claims and track their progress"
            }
            mobileAppBackend = container "Mobile App Backend" {
                description "Serves the insurer's mobile app"
            }
            claimsIntakeService = container "Claims Intake Service" {
                description "Registers new claims"
            }
            triageService = container "Triage Service" {
                description "Classifies and prioritizes claims"
            }
            assessmentService = container "Assessment Service" {
                description "Calculates settlement amounts"
            }
            payoutService = container "Payout Service" {
                description "Executes claim settlements"
            }
            fraudScreeningService = container "Fraud Screening Service" {
                description "Flags suspicious claims"
            }
            documentService = container "Document Service" {
                description "Accepts claim photos and reports"
            }
            notificationService = container "Notification Service" {
                description "Emails and messages policyholders"
            }
            assignmentService = container "Assignment Service" {
                description "Routes claims to adjusters"
            }
            adjusterWorkbench = container "Adjuster Workbench" {
                description "Where staff process their assigned claims"
            }
            policyVerificationService = container "Policy Verification Service" {
                description "Checks that a claim is covered by the policy"
            }
            reinsuranceAllocationService = container "Reinsurance Allocation Service" {
                description "Apportions large losses across reinsurance partners"
            }
            batchScheduler = container "Batch Scheduler" {
                description "Runs the nightly reserves calculation"
            }
            eventQueue = container "Event Queue" {
                description "Carries claim events between the application parts"
            }
            claimsDatabase = container "Claims Database" "Database" {
                description "Stores claim records"
            }
            policyDatabase = container "Policy Database" "Database" {
                description "Stores policy and cover records"
            }
            auditDatabase = container "Audit Database" "Database" {
                description "Stores the compliance audit trail"
            }
            documentStore = container "Document Store" "File Store" {
                description "Holds claim photos, reports, and correspondence"
            }
        }

        claimsDataBureau = softwareSystem "National Claims Data Bureau" {
            description "Operated by a different organization"
        }
        clearingHouse = softwareSystem "Clearing House" {
            description "Operated by a different organization"
        }

        policyholder -> webPortal "Reports claims and tracks their progress"
        policyholder -> mobileAppBackend "Reports claims and tracks their progress via the insurer's mobile app"
        adjuster -> adjusterWorkbench "Processes assigned claims"

        webPortal -> claimsIntakeService
        webPortal -> assessmentService
        webPortal -> payoutService
        webPortal -> documentService
        webPortal -> notificationService
        mobileAppBackend -> claimsIntakeService
        mobileAppBackend -> assessmentService
        mobileAppBackend -> payoutService
        mobileAppBackend -> documentService
        mobileAppBackend -> notificationService

        claimsIntakeService -> triageService "Hands accepted claims"
        triageService -> assessmentService "Routes claims"
        assessmentService -> payoutService "Requests settlements"

        fraudScreeningService -> claimsDataBureau "Consults"
        payoutService -> clearingHouse "Executes settlements through"

        assignmentService -> adjusterWorkbench "Routes claims"

        documentService -> documentStore "Reads from"
        batchScheduler -> claimsDatabase "Reads and writes"
        batchScheduler -> policyDatabase "Reads and writes"
        notificationService -> policyholder "Reports claim status changes"
    }
}`;
const [validate, parse, inspect] = await Promise.all([
  tools.structurizr.validate({ dsl }),
  tools.structurizr.parse({ dsl }),
  tools.structurizr.inspect({ dsl }),
]);
return JSON.stringify({ validate, parse, inspect }, null, 2);

